import { ComponentDef } from '../../components/types';
import {
  drawCodeAnnotation,
  drawComponentLink,
  drawExplanation,
  drawLabel,
  drawStepBox,
  drawTensor,
  fmtNum,
  Sel
} from '../primitives';
import { renderGenericDetailed } from './generic';
import { StepInfo } from './index';
import * as d3 from 'd3';

export function renderTransformerBlockDetailed(
  g: Sel,
  params: Record<string, number | string>,
  _meta: ComponentDef,
  _graph: import('../../graph/types').ComputationGraph
): { width: number; height: number; steps: StepInfo[] } {
  const variant = String(params.variant || 'pre-norm');
  if (variant !== 'pre-norm') {
    const variantMeta: ComponentDef = {
      ..._meta,
      name: 'Transformer Block (Post-Norm)',
      description: 'Post-normalization applies LayerNorm after the residual addition, the original Transformer design.'
    };
    return renderGenericDetailed(g, params, variantMeta, _graph);
  }

  const dModel = (params.d_model as number) || 512;
  const nHeads = (params.n_heads as number) || 8;
  const seqLen = (params.seq_len as number) || 128;
  const dFf = (params.d_ff as number) || 2048;
  const totalW = 800;
  const cx = totalW / 2;
  let y = 30;

  const dModelSel = g as unknown as d3.Selection<SVGGElement, unknown, null, undefined>;

  // Header
  drawLabel(g, cx, y, 'Transformer Block', { size: 16, weight: '700' });
  y += 22;
  drawLabel(g, cx, y, `d_model=${dModel}  n_heads=${nHeads}  seq_len=${seqLen}  d_ff=${dFf}`, {
    size: 10, color: '#888'
  });
  y += 40;

  // Input tensor
  drawTensor(g, cx - 110, y, 220, 30, `x: [b, ${seqLen}, ${dModel}]`, '#e8f5e9', '#4caf50');
  y += 50;

  const residualStartY = y - 15;

  // Step 1: Pre-norm attention
  const grp1 = dModelSel.append('g').attr('class', 'step-node step-tb-1').attr('transform', `translate(0, ${y})`);
  drawStepBox(grp1 as unknown as Sel, cx - 130, 0, 260, 46, 'Pre-Norm Attention Sub-layer', {
    step: 1, fill: '#e3f2fd', stroke: '#1976d2',
    formula: 'norm(x) → MHA(norm(x))'
  });
  y += 60;

  const attnDetailGrp = dModelSel.append('g').attr('class', 'step-node step-tb-1');
  drawLabel(attnDetailGrp as unknown as Sel, cx, y, 'LayerNorm', { size: 10, color: '#666' });
  y += 18;
  drawLabel(attnDetailGrp as unknown as Sel, cx, y, 'Multi-Head Attention', { size: 11, weight: '600', color: '#1565c0' });
  y += 40;

  // Step 2: First residual add
  const grp2 = dModelSel.append('g').attr('class', 'step-node step-tb-2').attr('transform', `translate(0, ${y})`);
  drawStepBox(grp2 as unknown as Sel, cx - 120, 0, 240, 46, 'Residual Connection', {
    step: 2, fill: '#e8f5e9', stroke: '#4caf50',
    formula: 'x1 = x + MHA(LN(x))'
  });
  y += 60;

  // Draw residual path from before step 1 to after step 2
  const resGrp1 = dModelSel.append('g').attr('class', 'step-node step-tb-2');
  drawResidualPath(resGrp1 as unknown as Sel, cx + 150, residualStartY, y - 35, cx + 80);

  const residualMidY = y - 15;

  // Step 3: Pre-norm MLP
  const grp3 = dModelSel.append('g').attr('class', 'step-node step-tb-3').attr('transform', `translate(0, ${y})`);
  drawStepBox(grp3 as unknown as Sel, cx - 130, 0, 260, 46, 'Pre-Norm MLP Sub-layer', {
    step: 3, fill: '#fff3e0', stroke: '#f57c00',
    formula: 'norm(x1) → MLP(norm(x1))'
  });
  y += 60;

  const mlpDetailGrp = dModelSel.append('g').attr('class', 'step-node step-tb-3');
  drawLabel(mlpDetailGrp as unknown as Sel, cx, y, 'LayerNorm', { size: 10, color: '#666' });
  y += 18;
  drawLabel(mlpDetailGrp as unknown as Sel, cx, y, 'Feed-Forward Network', { size: 11, weight: '600', color: '#e65100' });
  y += 40;

  // Step 4: Second residual add
  const grp4 = dModelSel.append('g').attr('class', 'step-node step-tb-4').attr('transform', `translate(0, ${y})`);
  drawStepBox(grp4 as unknown as Sel, cx - 120, 0, 240, 46, 'Residual Connection', {
    step: 4, fill: '#e8f5e9', stroke: '#4caf50',
    formula: 'out = x1 + MLP(LN(x1))'
  });
  y += 60;

  // Draw residual path from after step 2 to after step 4
  const resGrp2 = dModelSel.append('g').attr('class', 'step-node step-tb-4');
  drawResidualPath(resGrp2 as unknown as Sel, cx + 150, residualMidY, y - 35, cx + 80);

  // Output tensor
  drawTensor(g, cx - 110, y, 220, 30, `out: [b, ${seqLen}, ${dModel}]`, '#e8f5e9', '#4caf50');
  y += 50;

  // Parameter count
  const attnParams = dModel * dModel * 4;
  const mlpParams = dModel * dFf * 2;
  const normParams = dModel * 2;
  const totalParams = attnParams + mlpParams + normParams;
  drawLabel(g, cx, y, `Total params: ${fmtNum(totalParams)}  (attn ${fmtNum(attnParams)} + mlp ${fmtNum(mlpParams)} + norm ${fmtNum(normParams)})`, {
    size: 11, color: '#1976d2', weight: '600'
  });
  y += 28;

  // Explanations
  y = drawExplanation(g, 80, y, totalW - 160,
    'Residual connections allow gradients to flow directly through the network, making it feasible to train very deep models. '
    + 'Pre-normalization (LayerNorm before each sub-layer) stabilizes training compared to the original post-norm design.',
    'insight'
  );
  y += 6;

  y = drawExplanation(g, 80, y, totalW - 160,
    `A decoder-only model with L layers has ${fmtNum(totalParams)} params per block and costs roughly `
    + `${fmtNum(6 * dModel * dModel + 4 * dModel * dFf)} FLOPs per token per layer when using causal self-attention.`,
    'perf'
  );
  y += 6;

  // Cross-links
  drawComponentLink(g, cx - 150, y, 120, 24, 'attention', 'View Attention ↗', {
    fill: '#e3f2fd', stroke: '#1976d2'
  });
  drawComponentLink(g, cx + 30, y, 120, 24, 'mlp', 'View MLP ↗', {
    fill: '#fff3e0', stroke: '#f57c00'
  });
  y += 40;

  // Code annotation
  y = drawCodeAnnotation(g, 80, y, totalW - 160,
    'Transformer Decoder Block — Attention Is All You Need (Vaswani et al. 2017)',
    [
      'Each block applies pre-norm attention and pre-norm MLP with residual connections.',
      'Modern variants may use RMSNorm, SwiGLU, and rotary position embeddings.',
      `Params per block: ${fmtNum(totalParams)}.`
    ],
    [
      `self.ln1 = nn.LayerNorm(${dModel})`,
      `self.attn = MultiHeadAttention(${dModel}, ${nHeads})`,
      `self.ln2 = nn.LayerNorm(${dModel})`,
      `self.mlp = MLP(${dModel}, ${dFf})`,
      '',
      `def forward(self, x):  # x: [batch, seq, ${dModel}]`,
      `    x = x + self.attn(self.ln1(x))`,
      `    x = x + self.mlp(self.ln2(x))`,
      `    return x`
    ]
  );

  const steps: StepInfo[] = [
    {
      id: 1, label: 'Pre-Norm Attention Sub-layer', shortLabel: 'Attention',
      formula: 'MHA(LayerNorm(x))',
      explanation: `LayerNorm stabilizes the input before multi-head attention. The attention sub-layer computes ${nHeads} parallel attention heads, each with d_head=${Math.floor(dModel / nHeads)}, then concatenates and projects back to d_model=${dModel}.`,
      code: { title: 'Pre-Norm + Attention', lines: [
        `self.ln1 = nn.LayerNorm(${dModel})`,
        `self.attn = MultiHeadAttention(${dModel}, ${nHeads})`,
        '',
        `attn_out = self.attn(self.ln1(x))`,
        `# ln params: ${fmtNum(dModel * 2)} (weight + bias)`,
        `# attn params: ${fmtNum(attnParams)} (4 × ${dModel}²)`,
      ] },
      svgGroup: 'step-tb-1', color: '#1976d2', fill: '#e3f2fd',
    },
    {
      id: 2, label: 'Residual Connection', shortLabel: 'Residual 1',
      formula: 'x1 = x + MHA(LN(x))',
      explanation: 'The residual connection adds the original input back to the attention output. This allows gradients to bypass the attention sub-layer, enabling stable training of deep networks (hundreds of layers).',
      code: { title: 'Residual Add', lines: [
        `x = x + attn_out  # element-wise addition`,
        `# Shape preserved: [batch, seq, ${dModel}]`,
        `# No additional parameters`,
      ] },
      svgGroup: 'step-tb-2', color: '#4caf50', fill: '#e8f5e9',
    },
    {
      id: 3, label: 'Pre-Norm MLP Sub-layer', shortLabel: 'MLP',
      formula: 'MLP(LayerNorm(x1))',
      explanation: `A second LayerNorm followed by the feed-forward network. The MLP expands to d_ff=${dFf} (${Math.round(dFf / dModel)}× d_model), applies a non-linearity, then projects back. This is where most of the model's "knowledge" is stored.`,
      code: { title: 'Pre-Norm + MLP', lines: [
        `self.ln2 = nn.LayerNorm(${dModel})`,
        `self.mlp = MLP(${dModel}, ${dFf})`,
        '',
        `mlp_out = self.mlp(self.ln2(x))`,
        `# mlp params: ${fmtNum(mlpParams)} (W1: ${dModel}×${dFf} + W2: ${dFf}×${dModel})`,
      ] },
      svgGroup: 'step-tb-3', color: '#f57c00', fill: '#fff3e0',
    },
    {
      id: 4, label: 'Residual Connection', shortLabel: 'Residual 2',
      formula: 'out = x1 + MLP(LN(x1))',
      explanation: 'The second residual connection adds the MLP output back to x1. After this, the block is complete and the output is passed to the next block (or to the final layer norm and LM head if this is the last block).',
      code: { title: 'Residual Add', lines: [
        `x = x + mlp_out  # element-wise addition`,
        `# Shape preserved: [batch, seq, ${dModel}]`,
        `return x`,
      ] },
      svgGroup: 'step-tb-4', color: '#4caf50', fill: '#e8f5e9',
    },
  ];

  return { width: totalW, height: y + 20, steps };
}

function drawResidualPath(
  g: Sel,
  x: number,
  startY: number,
  endY: number,
  endX: number
): void {
  const path = `M ${endX},${startY} L ${x},${startY} L ${x},${endY} L ${endX - 14},${endY}`;
  g.append('path')
    .attr('d', path)
    .attr('fill', 'none')
    .attr('stroke', '#4caf50')
    .attr('stroke-width', 1.5)
    .attr('stroke-dasharray', '5,3')
    .attr('opacity', 0.7);
  drawLabel(g, x - 6, (startY + endY) / 2, 'residual', {
    size: 8, color: '#4caf50', anchor: 'end'
  });
}
